def _validate_payload(data):
    """Validate the structure of an incoming request payload."""
    if not isinstance(data, dict):
        raise TypeError("data must be a dictionary")

    for key in data:
        if not isinstance(key, str):
            raise TypeError("data keys must be strings")


def handle_request(data, legacy_mode=False):
    """Validate an incoming API request payload before processing it.

    Args:
        data: The request payload. It must be a dictionary with string keys
            unless ``legacy_mode`` is enabled.
        legacy_mode: If true, bypass payload validation for older clients.

    Raises:
        TypeError: If validation is enabled and data is not a dictionary or
            contains non-string keys.
    """
    if not legacy_mode:
        _validate_payload(data)

    return process(data)

